import {compareSavedCouncils,MAX_SAVED} from './council-saves.mjs';
import {councilFeedbackMarkup} from './council-report.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=s=>new Date(s).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});
const action=(text,name,id='',extra='')=>`<button class="text-button" data-action="${name}" data-id="${esc(id)}" ${extra}>${text}</button>`;
const title=item=>`${date(item.completedAt)} · ${item.decision.title}`;
export function previousSaved(items,item){const i=items.findIndex(x=>x.id===item.id);return items.slice(i+1).find(x=>x.topic===item.topic&&x.caseVersion===item.caseVersion);}
export function savedCouncilsMarkup(items,error,notice,pendingDelete){
 return `<section class="saved-councils" aria-labelledby="saved-title"><div class="section-line"><h2 id="saved-title" tabindex="-1">Your saved councils</h2><span class="outline-badge">${items.length} / ${MAX_SAVED} SAVED</span></div><p>Completed councils and their feedback stay in this browser, including question excerpts. The most recent ${MAX_SAVED} are kept. They are not uploaded or synced; clearing browser data removes them. In-progress councils and other practice rounds reset on refresh.</p>${error?`<p class="notice" role="status">${esc(error)}</p>`:''}${notice?`<p class="notice" role="status">${esc(notice)}</p>`:''}${pendingDelete?`<div class="saved-delete" role="group" aria-label="Confirm deletion"><p>${pendingDelete==='all'?'Delete all saved councils in this browser?':'Delete this saved council?'} This cannot be undone.</p>${action('Confirm deletion','saved-delete-confirm')}${action('Keep saved attempts','saved-delete-cancel')}</div>`:''}${items.length?`<div class="saved-list">${items.map(item=>`<article><div><p class="eyebrow">${esc(date(item.completedAt))} · ${item.origin==='interview'?'INTERVIEW PREPARATION':'GENERAL PRACTICE'}</p><h3>${esc(item.title)}</h3><p>${esc(item.decision.title)} · ${item.records.length} records inspected · ${item.used}/${item.capacity} work units · ${item.deferred.length} response items deferred</p></div><div class="saved-actions">${action('Review feedback','saved-open',item.id)}${action('Compare with previous','saved-compare',item.id,previousSaved(items,item)?'':'disabled')}${action('Delete','saved-delete',item.id)}</div></article>`).join('')}</div>${action('Delete all saved councils','saved-clear')}`:`<div class="empty-state"><h3>Your first saved council starts here.</h3><p>Finish both rounds of Accessibility or Platform / API. The completed attempt will save automatically.</p>${error?action('Clear unreadable saved history','saved-clear'):''}</div>`}</section>`;
}
export function savedCouncilMarkup(item){return item?`<div class="session-top">${action('← Saved councils','activity')}<span class="outline-badge">SAVED COPY · READ ONLY</span></div><h1 tabindex="-1">${esc(item.title)}</h1><p>${esc(date(item.completedAt))} · ${esc(item.decision.title)}. This is the feedback saved when you completed this attempt.</p>${councilFeedbackMarkup(item.feedback)}`:`<p class="notice">This saved attempt is no longer available.</p>${action('← Saved councils','activity')}`;}
export function councilComparisonMarkup(items,ids){
 const a=items.find(x=>x.id===ids[0]),b=items.find(x=>x.id===ids[1]);
 if(!a||!b)return `<p class="notice">Choose two saved attempts of the same council.</p>${action('← Saved councils','activity')}`;
 const eligible=items.filter(x=>x.topic===a.topic&&x.caseVersion===a.caseVersion);
 const ordered=[a,b].sort((x,y)=>items.indexOf(y)-items.indexOf(x));
 const comparison=compareSavedCouncils(ordered[0],ordered[1]);
 const select=(label,id,current)=>`<div><label for="${id}">${label}</label><select id="${id}">${eligible.map(x=>`<option value="${esc(x.id)}" ${x.id===current?'selected':''}>${esc(title(x))}</option>`).join('')}</select></div>`;
 return `<div class="session-top">${action('← Saved councils','activity')}<span class="outline-badge">COMPARE RETRIES</span></div><h1 tabindex="-1">What changed<br>between attempts?</h1><p class="lede">${esc(a.title)} · Compare the evidence, bargains and work. More support or spending alone does not establish improvement.</p><div class="saved-selectors">${select('Attempt A','saved-earlier',a.id)}${select('Attempt B','saved-later',b.id)}</div>${comparison?`<div class="saved-table-wrap"><table class="saved-comparison"><caption>Earlier: ${esc(date(ordered[0].completedAt))} · Later: ${esc(date(ordered[1].completedAt))}</caption><thead><tr><th scope="col">What to compare</th><th scope="col">Earlier attempt</th><th scope="col">Later attempt</th></tr></thead><tbody>${comparison.rows.map(r=>`<tr><th scope="row">${esc(r.label)}</th><td>${esc(r.before)}</td><td>${esc(r.after)}</td></tr>`).join('')}</tbody></table></div><section class="council-coach-rehearsal"><h2>Changes worth reflecting on</h2><ul>${comparison.changes.map(c=>`<li>${esc(c)}</li>`).join('')}</ul><p><strong>Ask yourself:</strong> ${esc(comparison.prompt)}</p></section><details class="saved-feedback-pair"><summary>Compare the saved feedback</summary><div class="saved-feedback-grid">${ordered.map((item,i)=>`<section><h2>${i?'Later':'Earlier'} attempt</h2>${item.feedback.sections.map(s=>`<article><h3>${esc(s.title)}</h3><p>${esc(s.summary)}</p><p><strong>Next-time prompt:</strong> ${esc(s.next)}</p></article>`).join('')}${action('Open full feedback','saved-open',item.id)}</section>`).join('')}</div></details><p class="council-muted">${comparison.limits.map(esc).join(' ')}</p>`:'<p class="notice" role="status">Select two different attempts of the same council version.</p>'}`;
}
